// Real Chromium + shipped SxLock functions. Fixtures are generated by make_fixtures.py.
// DATA_DIR=/absolute/test-data PLAYWRIGHT_MODULE=/path/to/playwright BROWSER_EXECUTABLE=/path/to/chrome node media-regression.cjs
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const repo=path.resolve(__dirname,'../../../..'),data=path.resolve(process.env.DATA_DIR);
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
async function main(){
 const server=http.createServer(async(q,s)=>{
  const url=new URL(q.url,'http://test');
  if(q.method==='POST'&&url.pathname.startsWith('/results/')){
   const chunks=[];for await(const b of q)chunks.push(b);
   fs.writeFileSync(path.join(data,path.basename(url.pathname)),Buffer.concat(chunks));s.end('saved');return;
  }
  const baseline=url.pathname.startsWith('/baseline/');
  const base=url.pathname.startsWith('/fixtures/')?data:baseline?path.join(data,'baseline'):repo;
  const relative=decodeURIComponent(url.pathname.replace(/^\/(repo|baseline|fixtures)\//,''));
  let file=path.resolve(base,relative);
  if(!file.startsWith(base+path.sep)){s.writeHead(403);s.end();return;}
  if(baseline&&!fs.existsSync(file))file=path.resolve(repo,relative);
  try{const st=fs.statSync(file);let start=0,end=st.size-1;
   if(q.headers.range){const m=q.headers.range.match(/bytes=(\d+)-(\d*)/);start=Number(m[1]);if(m[2])end=Number(m[2]);s.statusCode=206;s.setHeader('Content-Range',`bytes ${start}-${end}/${st.size}`);}
   s.setHeader('Content-Type',/\.m?js$/.test(file)?'text/javascript':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':file.endsWith('.json')?'application/json':file.endsWith('.mp4')?'video/mp4':'application/octet-stream');
   s.setHeader('Content-Length',end-start+1);s.setHeader('Accept-Ranges','bytes');fs.createReadStream(file,{start,end}).pipe(s);
  }catch{s.writeHead(404);s.end('not found');}
 }).listen(0,'127.0.0.1');
 await new Promise(r=>server.on('listening',r));
 const args=['--no-sandbox','--autoplay-policy=no-user-gesture-required','--disable-dev-shm-usage'];
 const browser=await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE||undefined,args,headless:true});
 const base='http://127.0.0.1:'+server.address().port;
 const page=await browser.newPage({viewport:{width:1000,height:1200},acceptDownloads:true});
 page.on('console',m=>{if(m.type()!=='error')console.log(m.text())});
 page.on('pageerror',e=>console.error('PAGE ERROR',e.message));
 try{
  await page.goto(base+'/repo/tools-home/tools/sxlock/index.html');
  await page.waitForFunction(()=>window.SxLock);await page.evaluate(()=>SxLock.ready);
  if(process.env.BASELINE_ONLY!=='1'){
  const results=await page.evaluate(async()=>{
   const engine=await import('./export-engine.mjs');
   const file=await(await fetch('/fixtures/fixture_40s.mp4')).blob();
   const ac=await SxLock.audioContext(),sound=ac.createBuffer(2,4800,48000);
   for(let c=0;c<2;c++)for(let i=0;i<sound.length;i++)sound.getChannelData(c)[i]=Math.sin(i/48000*2*Math.PI*2700)*.025;
   SxLock.sounds.set('regression-fx',{id:'regression-fx',name:'Regression tone',origin:'import',buffer:sound,builtin:true});
   document.getElementById('effectsBus').value=100;
   const cue=(start,duration=.1,loop=false)=>({soundId:'regression-fx',start,duration,loop,offset:0,volume:100,enabled:true});
   const off=new OfflineAudioContext(2,8*48000,48000);
   SxLock.placeSource(off,cue(863/25),sound,off.destination,32,0,40);
   const pcm=(await off.startRendering()).getChannelData(0),firstSample=(863-800)*1920;
   if(pcm.subarray(0,firstSample+1).some(x=>Math.abs(x)>1e-8)
      ||Math.abs(pcm[firstSample+1]-sound.getChannelData(0)[1])>1e-7)throw Error('F863 effect sample placement moved');
   const cases={C:[],D:[cue(2)],E:[cue(2),cue(16),cue(34.52),cue(39.8)],F:[cue(16,1.5,true),cue(16.04,.8,true)],G:[cue(34.48),cue(34.52),cue(34.56)],Moved:[cue(4),cue(34.52)],Deleted:[]};
   const results={};
   async function render(name,source,cues,extra={}){
    console.log('TEST '+name);
    const out=await engine.exportVideo({file:source,hasEffects:cues.length>0,...extra,
     placeEffects:async(off,at,end)=>{for(const c of cues)if(c.enabled)SxLock.placeSource(off,c,sound,off.destination,at,0,end)}});
    await fetch('/results/'+name+'.mp4',{method:'POST',body:out.blob});results[name]=out.report;return out.blob;
   }
   let repeat;
   for(const [name,cues] of Object.entries(cases)){const blob=await render(name,file,cues);if(name==='E')repeat=blob;}
   await render('H',repeat,[]);
   for(const name of ['fixture_44100','fixture_audio_offset','fixture_30fps','color_full709']){
    const source=await(await fetch('/fixtures/'+name+'.mp4')).blob();await render(name+'_out',source,[cue(2)]);
   }
   const shortAudio=await(await fetch('/fixtures/fixture_30fps_short_audio.mp4')).blob();
   await render('fixture_30fps_short_audio_out',shortAudio,[]);
   if(results.fixture_30fps_short_audio_out.audio!=='packet-copy')throw Error('Short original audio was unnecessarily encoded');
   // Define alpha inputs independently of the browser's live capture and compositor.
   const alpha=(await(await fetch('/fixtures/full-range-alpha.webm')).blob()).slice(0,undefined,'video/webm');
   const width=160,height=288;
   await fetch('/results/Alpha.webm',{method:'POST',body:alpha});
   const alphaOut=await render('Alpha',alpha,[cue(.2,.04)]);
   async function display(blob){
    const v=document.createElement('video'),url=URL.createObjectURL(blob);
    v.muted=true;
    v.preload='auto';
    v.style.cssText='position:fixed;top:0;left:0;z-index:100;width:160px;height:288px';
    document.body.append(v);
    try{
     await new Promise((resolve,reject)=>{
      v.onloadeddata=resolve;
      v.onerror=()=>reject(Error('Colour test video failed'));
      v.src=url;
     });
     await new Promise(resolve=>{v.onseeked=resolve;v.currentTime=.16;});
     const c=document.createElement('canvas');
     c.width=width;c.height=height;
     const g=c.getContext('2d',{colorSpace:'srgb'});
     g.drawImage(v,0,0);
     return g.getImageData(0,0,width,height).data;
    }finally{v.remove();URL.revokeObjectURL(url);}
   }
   const ref=await display(alpha),encoded=await display(alphaOut),m=await import('./vendor/mediabunny-1.62.1-gs1.mjs');
   const alphaInput=new m.Input({formats:m.ALL_FORMATS,source:new m.BlobSource(alpha)}),track=await alphaInput.getPrimaryVideoTrack();
   const sample=await new m.VideoSampleSink(track).getSample(.16),frame=sample.toVideoFrame();
   if(!frame.format.includes('A'))throw Error('Colour fixture lacks the alpha-merge path');
   const c=document.createElement('canvas');c.width=width;c.height=height;const g=c.getContext('2d',{colorSpace:'srgb'});g.drawImage(frame,0,0);const decoded=g.getImageData(0,0,width,height).data;
   function compare(p,{opaqueOnly=false}={}){
    let absolute=0,count=0;
    const sum=[0,0,0];
    for(let i=0;i<p.length;i+=4){
     if(opaqueOnly&&decoded[i+3]!==255)continue;
     for(let channel=0;channel<3;channel++){
      const delta=p[i+channel]-ref[i+channel];
      absolute+=Math.abs(delta);
      sum[channel]+=delta;
     }
     count++;
    }
    return {mae:absolute/(count*3),meanRGB:sum.map(value=>value/count)};
   }
   const color=await track.getColorSpace();
   const transparentAlpha=decoded[(36*width+3)*4+3],colorRed=ref[(36*width+120)*4];
   if(!color.fullRange||color.primaries!=='bt709'||colorRed<160||transparentAlpha!==0){
    throw Error('Full-range alpha test fixture is invalid: '+JSON.stringify({color,colorRed,transparentAlpha}));
   }
   // The H.264 export is opaque. Compare its color where picture pixels are visible.
   results.AlphaColour={source:color,decoded:compare(decoded),encoded:compare(encoded,{opaqueOnly:true}),format:frame.format};
   frame.close();sample.close();alphaInput.dispose();
   if(results.AlphaColour.decoded.mae>.1||results.AlphaColour.encoded.meanRGB.some(v=>Math.abs(v)>1.5)||results.AlphaColour.encoded.mae>4)throw Error('Alpha WebM colour changed: '+JSON.stringify(results.AlphaColour));
   // Cancellation must not offer a partial file or alter the next job.
   let cancel=false;
   try{await engine.exportVideo({file,hasEffects:true,cancelled:()=>cancel,onProgress:()=>{cancel=true}});throw Error('Cancellation was ignored');}
   catch(e){if(!e.message.includes('cancelled'))throw e;results.cancelled=true;}
   await render('AfterCancel',file,[]);
   return results;
  });
  fs.writeFileSync(path.join(data,'regression.json'),JSON.stringify(results,null,2));
  assert.equal(results.C.video,'file-copy');assert.equal(results.H.video,'file-copy');assert.equal(results.E.outputFrames,1000);
  // Start a fresh document so earlier exports have not registered software AAC.
  // A device can advertise native AAC even when its encoder cannot produce the intended track.
  await page.reload();
  await page.waitForFunction(()=>window.SxLock);
  await page.evaluate(async()=>{
   await SxLock.ready;
   window.AudioEncoder=class {
    static async isConfigSupported(config){return {supported:true,config};}
    constructor(){throw Error('SxLock mixed MP4 attempted to use the device AAC encoder');}
   };
  });
  await page.locator('#videoFile').setInputFiles(path.join(data,'fixture_30fps_phone.mp4'));
  await page.waitForFunction(()=>document.getElementById('video').readyState>=2&&!document.getElementById('play').disabled);
  await page.getByRole('button',{name:'View',exact:true}).click();
  const view=page.getByRole('dialog',{name:'Preview view'});
  await view.getByRole('button',{name:'Zoom in'}).click();
  await view.getByRole('button',{name:'Shorter'}).click();
  await view.getByRole('button',{name:'Close preview view'}).click();
  const start=await page.evaluate(async()=>{const c=await SxLock.insert('cricket',{start:.101,volume:20});return c.start});
  assert.equal(start,.12);
  await page.locator('#exportSection').evaluate(el=>{el.open=true;el.querySelector('details').open=true;});
  await page.locator('#fps').selectOption('30');
  await page.locator('#exportVideo').click();
  await page.waitForFunction(()=>!document.getElementById('exportVideo').disabled,null,{timeout:120000});
  assert(await page.locator('#result').isVisible(),await page.locator('#status').textContent());
  const download=page.waitForEvent('download');await page.locator('#download').click();await(await download).saveAs(path.join(data,'UI.mp4'));
  console.log('PASS: engine matrix, cancellation, frame placement and UI export/download');
  // Exercise the Toolbox insertion through the preview and both mixed exports.
  const soundPage=await browser.newPage({acceptDownloads:true});
  await soundPage.goto(base+'/repo/tools-home/tools/sxlock/index.html');
  await soundPage.waitForFunction(()=>window.SxLock);
  await soundPage.evaluate(()=>SxLock.ready);
  const control=id=>soundPage.locator('#'+id);
  await control('videoFile').setInputFiles(path.join(data,'fixture_landscape.mp4'));
  await soundPage.waitForFunction(()=>document.getElementById('video').readyState>=2&&!document.getElementById('play').disabled);
  await control('bed').evaluate(slider=>{slider.value=0;slider.dispatchEvent(new Event('input',{bubbles:true}));});
  await control('openToolbox').click();
  await control('toolboxFiles').setInputFiles(path.join(data,'color_full709.mp4'));
  await soundPage.getByRole('button',{name:'Overlay color_full709.mp4',exact:true}).click();
  await soundPage.getByRole('button',{name:'Edit insertion color_full709.mp4',exact:true}).first().click();
  await control('visualIn').fill('25');
  await control('visualIn').press('Tab');
  await control('visualOut').fill('75');
  await control('visualOut').press('Tab');
  await control('visualGoIn').click();
  const audio=control('visualAudio'), clip=soundPage.locator('.sx-visual-item video');
  assert.equal(await audio.locator('summary').textContent(),'Audio · No sound');
  assert.equal(await clip.evaluate(video=>video.muted),true);
  await audio.locator('summary').click();
  await control('visualVolume').fill('25');
  await control('visualVolume').press('Tab');
  await soundPage.waitForFunction(()=>!document.querySelector('.sx-visual-item video').muted);
  await audio.getByRole('button',{name:'No sound',exact:true}).click();
  assert.equal(await clip.evaluate(video=>video.muted),true);
  await control('visualClose').click();
  await control('exportSection').locator(':scope > summary').click();
  const save=async(id,name)=>{
   await control(id).click();
   await soundPage.waitForFunction(button=>!document.getElementById(button).disabled,id,{timeout:30000});
   assert(await control('result').isVisible(),await control('status').textContent());
   const ready=soundPage.waitForEvent('download');
   await control('download').click();
   await (await ready).saveAs(path.join(data,name));
  };
  await save('exportWav','overlay-muted.wav');
  await control('openToolbox').click();
  await soundPage.getByRole('button',{name:'Edit insertion color_full709.mp4',exact:true}).first().click();
  await audio.getByRole('button',{name:'Sound on',exact:true}).click();
  assert.equal(await control('visualVolume').inputValue(),'25');
  await control('visualGoIn').click();
  await control('visualClose').click();
  await control('play').click();
  await soundPage.waitForFunction(()=>{const v=document.querySelector('.sx-visual-item video');return !v.paused&&!v.muted&&v.playbackRate>1;});
  await control('play').click();
  await save('exportWav','overlay-mixed.wav');
  await save('exportVideo','overlay-mixed.mp4');
  const levels=await soundPage.evaluate(async files=>{
   const m=await import('./vendor/mediabunny-1.62.1-gs1.mjs');
   return Promise.all(files.map(async name=>{
    const blob=await (await fetch('/fixtures/'+name)).blob();
    const input=new m.Input({formats:m.ALL_FORMATS,source:new m.BlobSource(blob)});
    const track=await input.getPrimaryAudioTrack();
    const peaks=[0,0,0];
    try{
     for await(const {buffer,timestamp} of new m.AudioBufferSink(track).buffers()){
      const data=buffer.getChannelData(0);
      for(let i=0;i<data.length;i++){
       const t=timestamp+i/buffer.sampleRate;
       const region=t<.8?0:t>1.2&&t<2.8?1:t>3.2?2:-1;
       if(region>=0)peaks[region]=Math.max(peaks[region],Math.abs(data[i]));
      }
     }
     return peaks;
    }finally{input.dispose();}
   }));
  },['overlay-muted.wav','overlay-mixed.wav','overlay-mixed.mp4']);
  assert.deepEqual(levels[0],[0,0,0]);
  for(const [before,active,after] of levels.slice(1)){
   assert.ok(before<.003&&active>.018&&active<.045&&after<.003,JSON.stringify(levels));
  }
  console.log('PASS SxLock visual insertion audio in preview, mixed WAV and finished video');
  await soundPage.evaluate(async()=>{
   const context=await SxLock.audioContext(), tone=context.createBuffer(1,4*48000,48000);
   const samples=tone.getChannelData(0);
   for(let i=0;i<samples.length;i++)samples[i]=Math.sin(i/48000*2*Math.PI*1500)*.08;
   SxLock.sounds.set('cue-fixture',{id:'cue-fixture',name:'Mix cue test tone',origin:'import',buffer:tone,builtin:true});
   await SxLock.insert('cue-fixture',{start:0,volume:100});
  });
  await control('insertionSection').evaluate(section=>section.open=true);
  await control('clips').locator('.clip-open').first().click();
  await control('effectAudioFades').locator('summary').click();
  for(const id of ['effectFadeIn','effectFadeOut']){
   await control(id).fill('1');
   await control(id).press('Tab');
  }
  await control('applyEffect').click();
  const go=soundPage.getByRole('spinbutton',{name:'Go to seconds'});
  await go.fill('1');
  await soundPage.getByRole('button',{name:'Go to time'}).click();
  await soundPage.waitForFunction(()=>document.getElementById('clock').textContent.endsWith('F25'));
  await control('mixerSection').evaluate(section=>section.open=true);
  await control('mixCuesSection').locator('summary').click();
  await control('addMixCue').click();
  assert.equal(await control('mixCuePosition').inputValue(),'25');
  await control('mixCueTransition').fill('50');
  await control('mixCueBed').fill('100');
  const saveCue=soundPage.getByRole('button',{name:'Save cue',exact:true});
  await saveCue.click();
  await control('addMixCue').click();
  await control('mixCuePosition').fill('50');
  await control('mixCueTransition').fill('25');
  await control('mixCueBed').fill('25');
  await control('mixCueEffects').fill('50');
  await saveCue.click();
  await soundPage.getByRole('button',{name:'Go to cue at F50',exact:true}).click();
  await soundPage.waitForFunction(()=>document.getElementById('clock').textContent.endsWith('F50'));
  assert.equal(await control('bedTimelineLevel').textContent(),'At playhead · 50%');
  assert.equal(await control('effectsTimelineLevel').textContent(),'At playhead · 100%');
  await save('exportWav','cue-mix.wav');
  await save('exportFx','cue-effects.wav');
  await save('exportVideo','cue-mix.mp4');
  const cueMix=await soundPage.evaluate(async names=>{
   const m=await import('./vendor/mediabunny-1.62.1-gs1.mjs');
   const times=[.5,1.5,2.5,3.5], frequencies=[480,1500];
   return Promise.all(names.map(async name=>{
    const blob=await (await fetch('/fixtures/'+name)).blob();
    const input=new m.Input({formats:m.ALL_FORMATS,source:new m.BlobSource(blob)});
    const stats=times.map(()=>frequencies.map(()=>[0,0,0]));
    try {
     const track=await input.getPrimaryAudioTrack();
     for await(const {buffer,timestamp} of new m.AudioBufferSink(track).buffers()){
      const samples=buffer.getChannelData(0), sr=buffer.sampleRate;
      for(const [i,at] of times.entries()){
       const from=Math.max(0,Math.ceil((at-.035-timestamp)*sr));
       const to=Math.min(samples.length,Math.ceil((at+.035-timestamp)*sr));
       for(let n=from;n<to;n++){
        for(const [j,f] of frequencies.entries()){
         const phase=(timestamp+n/sr)*f*2*Math.PI, totals=stats[i][j];
         totals[0]+=samples[n]*Math.cos(phase);
         totals[1]+=samples[n]*Math.sin(phase);
         totals[2]++;
        }
       }
      }
     }
     return stats.map(pair=>pair.map(([re,im,count])=>2*Math.hypot(re,im)/count));
    } finally {input.dispose();}
   }));
  },['cue-mix.wav','cue-effects.wav','cue-mix.mp4']);
  for(const [index,levels] of cueMix.entries()){
   const bed=index===1?[0,0,0,0]:[0,.03125,.046875,.03125];
   const effects=[.04,.08,.06,.02];
   for(let i=0;i<levels.length;i++){
    assert.ok(Math.abs(levels[i][0]-bed[i])<.009,JSON.stringify(cueMix));
    assert.ok(Math.abs(levels[i][1]-effects[i])<.009,JSON.stringify(cueMix));
   }
  }
  await soundPage.waitForFunction(()=>document.getElementById('recoveryStatus').textContent.startsWith('Saved locally'));
  await soundPage.reload();
  await soundPage.waitForFunction(()=>window.SxLock);
  await soundPage.evaluate(()=>SxLock.ready);
  const restored=await soundPage.evaluate(()=>SxLock.snapshot());
  assert.equal(restored.mixCues.length,2);
  assert.deepEqual(restored.mixCues.map(({start,transition,bed,effects})=>[start,transition,bed,effects]),[[1,2,100,undefined],[2,1,25,50]]);
  assert.equal(restored.clips.find(clip=>clip.soundId==='cue-fixture').fadeIn,1);
  assert.equal(restored.clips.find(clip=>clip.soundId==='cue-fixture').fadeOut,1);
  await soundPage.close();
  console.log('PASS SxLock cue seek, interrupted ramp, insertion fades, project recovery and decoded exports');

  }
  if(process.env.TEST_BASELINE==='1'){
   await page.goto(base+'/baseline/tools-home/tools/sxlock/index.html');
   await page.waitForFunction(()=>window.SxLock);await page.evaluate(()=>SxLock.ready);
   await page.locator('#videoFile').setInputFiles(path.join(data,'color_full709.mp4'));
   await page.waitForFunction(()=>document.getElementById('video').readyState>=2);
   await page.locator('#exportSection').evaluate(el=>el.open=true);
   await page.locator('#format').selectOption('video/mp4',{force:true});await page.locator('#exportVideo').click();
   await page.waitForFunction(()=>!document.getElementById('result').hidden,null,{timeout:30000});
   const d=page.waitForEvent('download');await page.locator('#download').click();await(await d).saveAs(path.join(data,'old_sxlock_color.mp4'));
   // Isolate the old H.264 video encoder even on Linux without native AAC encoding.
   await page.evaluate(()=>{const type='video/mp4;codecs=avc1.42001f,opus';document.getElementById('format').add(new Option('H.264 diagnostic',type));document.getElementById('format').value=type;document.getElementById('result').hidden=true;});
   await page.locator('#exportVideo').click();await page.waitForFunction(()=>!document.getElementById('result').hidden,null,{timeout:30000});
   const h=page.waitForEvent('download');await page.locator('#download').click();await(await h).saveAs(path.join(data,'old_sxlock_h264_color.mp4'));
   await page.goto(base+'/repo/tools-home/tools/aspectlock/index.html');
   await page.evaluate(async()=>{startFrame=9999;const file=await(await fetch('/fixtures/color_full709.mp4')).blob();bv.src=URL.createObjectURL(file);ov.src=URL.createObjectURL(file);await Promise.all([bv,ov].map(v=>new Promise(r=>v.onloadeddata=r)));});
   await page.locator('#render').click();await page.waitForFunction(()=>typeof renderedBlob!=='undefined'&&renderedBlob?.size>0,null,{timeout:30000});
   await page.evaluate(async()=>{await fetch('/results/aspectlock_color.webm',{method:'POST',body:renderedBlob});});
   console.log('PASS: actual baseline SxLock and unchanged AspectLock controlled captures');
  }
 }finally{await browser.close();server.close();}
}
main().catch(e=>{console.error(e);process.exit(1)});
